# G-Counter CRDT: grow-only counter across 3 nodes
class GCounter:
    def __init__(self, node_id: str, num_nodes: int):
        self.node_id = node_id
        self.counts = [0] * num_nodes  # index = node index
        self.idx = int(node_id.split('-')[1])

    def increment(self):
        self.counts[self.idx] += 1

    def value(self) -> int:
        return sum(self.counts)

    def merge(self, other: 'GCounter') -> 'GCounter':
        result = GCounter(self.node_id, len(self.counts))
        result.counts = [
            max(a, b) for a, b in zip(self.counts, other.counts)
        ]
        return result

# Two nodes increment independently, then merge
node0 = GCounter('node-0', 3)
node1 = GCounter('node-1', 3)
node0.increment(); node0.increment()   # node0 sees 2
node1.increment()                       # node1 sees 1
merged = node0.merge(node1)
print(merged.value())  # 3 — deterministic regardless of merge order

// Simplified operation-based counter (CmRDT)
type Op = { type: 'increment'; nodeId: string; seq: number };

class OpBasedCounter {
  private value = 0;
  private applied = new Set<string>();

  apply(op: Op): void {
    const key = `${op.nodeId}:${op.seq}`;
    if (this.applied.has(key)) return; // idempotency guard
    this.applied.add(key);
    this.value += 1;
  }

  read(): number {
    return this.value;
  }
}

// Each node broadcasts ops; causal delivery ensures order
const replica = new OpBasedCounter();
replica.apply({ type: 'increment', nodeId: 'A', seq: 1 });
replica.apply({ type: 'increment', nodeId: 'B', seq: 1 });
replica.apply({ type: 'increment', nodeId: 'A', seq: 1 }); // duplicate — ignored
console.log(replica.read()); // 2

# G-Set: state-based grow-only set CRDT
from dataclasses import dataclass, field
from typing import Set

@dataclass
class GSet:
    elements: Set[str] = field(default_factory=set)

    def add(self, element: str) -> None:
        self.elements.add(element)

    def value(self) -> Set[str]:
        return frozenset(self.elements)

    def merge(self, other: 'GSet') -> 'GSet':
        # Join = set union (least upper bound on subset lattice)
        return GSet(elements=self.elements | other.elements)

    def __le__(self, other: 'GSet') -> bool:
        return self.elements <= other.elements  # lattice order

a = GSet(); a.add('alice'); a.add('bob')
b = GSet(); b.add('bob'); b.add('carol')
merged = a.merge(b)
print(merged.value())  # frozenset({'alice', 'bob', 'carol'})
# merge is commutative, associative, idempotent

