import uuid
from dataclasses import dataclass, field
from typing import Dict, Set

@dataclass
class ORSet:
    """Observed-Remove Set CRDT — add wins on concurrent add/remove."""
    # element -> set of unique tokens for present adds
    _added: Dict[str, Set[str]] = field(default_factory=dict)
    _removed: Set[str] = field(default_factory=set)

    def add(self, element: str) -> str:
        token = str(uuid.uuid4())
        self._added.setdefault(element, set()).add(token)
        return token  # broadcast (element, token) as the operation

    def remove(self, element: str) -> None:
        # Remove all currently observed tokens for this element
        self._removed |= self._added.get(element, set())

    def value(self) -> Set[str]:
        # An element is present if it has at least one token not removed
        return {
            e for e, tokens in self._added.items()
            if tokens - self._removed
        }

    def merge(self, other: 'ORSet') -> 'ORSet':
        merged = ORSet()
        for e, tokens in (self._added | other._added).items():
            merged._added[e] = self._added.get(e, set()) | other._added.get(e, set())
        merged._removed = self._removed | other._removed
        return merged

# Delta-state G-Counter: ships only the changed slot as the delta
from dataclasses import dataclass, field
from typing import List, Optional

@dataclass
class DeltaGCounter:
    node_id: int
    num_nodes: int
    _slots: List[int] = field(init=False)

    def __post_init__(self):
        self._slots = [0] * self.num_nodes

    def increment(self, delta: int = 1) -> 'DeltaGCounter':
        """Mutate and return the delta (only own slot changed)."""
        self._slots[self.node_id] += delta
        # Delta: a GCounter with only the changed slot set
        d = DeltaGCounter(self.node_id, self.num_nodes)
        d._slots[self.node_id] = self._slots[self.node_id]
        return d  # ship this tiny delta to peers, not full _slots

    def join(self, other: 'DeltaGCounter') -> None:
        """Merge full state or delta — same semilattice join."""
        self._slots = [
            max(a, b) for a, b in zip(self._slots, other._slots)
        ]

    def value(self) -> int:
        return sum(self._slots)
